from taf.gnb.oam.coam.admin.exceptions import raise_value_error


class CCMUplink(object):
    def __init__(self, nrcell_rdn, nrarfcn_ul, reporting_time_interval, beam_pattern_id,
                 performance_test_type, ru_mode, phys_cell_id):
        self.nrcell_rdn = nrcell_rdn
        self.nrarfcn_ul = self.validate_param('nrarfcnUl',
                                              nrarfcn_ul,
                                              (nrarfcn_ul is None or (0 <= nrarfcn_ul <= 3279165)))
        self.reporting_time_interval = self.validate_param('reportingTimeInterval',
                                                           reporting_time_interval,
                                                           (1 <= reporting_time_interval <= 3600))
        self.beam_pattern_id = self.validate_param('beamPatternId',
                                                   beam_pattern_id,
                                                   (0 <= beam_pattern_id <= 1200))
        self.performance_test_type = self.validate_param('performanceTestType',
                                                         performance_test_type,
                                                         (performance_test_type in ['Pusch', 'Prach', 'Pucch']))
        self.ru_mode = self.validate_param('ruMode',
                                           ru_mode,
                                           (ru_mode in ['NR_Only', 'MSR']))
        self.phys_cell_id = self.validate_param('physCellId',
                                                phys_cell_id,
                                                (0 <= phys_cell_id <= 1007))

    @classmethod
    def from_response_dict(cls, response_dict):
        nrcell_rdn = response_dict['nrcell_rDN']
        nrarfcn_ul = response_dict['params']['nrarfcnUl'] if 'nrarfcnUl' in response_dict['params'] else None
        reporting_time_interval = response_dict['params']['reportingTimeInterval']
        beam_pattern_id = response_dict['params']['beamPatternId']
        performance_test_type = response_dict['params']['performanceTestType']
        ru_mode = response_dict['params']['ruMode']
        phys_cell_id = response_dict['params']['physCellId']

        return cls(nrcell_rdn=nrcell_rdn, nrarfcn_ul=nrarfcn_ul,
                   reporting_time_interval=reporting_time_interval,
                   beam_pattern_id=beam_pattern_id,
                   performance_test_type=performance_test_type,
                   ru_mode=ru_mode,
                   phys_cell_id=phys_cell_id
                   )

    def as_dict(self):
        attributes = {'nrcell_rDN': self.nrcell_rdn,
                      'params': {'nrarfcnUl': self.nrarfcn_ul,
                                 'reportingTimeInterval': self.reporting_time_interval,
                                 'beamPatternId': self.beam_pattern_id,
                                 'performanceTestType': self.performance_test_type,
                                 'ruMode': self.ru_mode,
                                 'physCellId': self.phys_cell_id
                                 }
                      }

        if attributes['params']['nrarfcnUl'] is None:
            del attributes['params']['nrarfcnUl']

        return attributes

    @staticmethod
    def validate_param(param, value, valid):
        return value if valid else raise_value_error(
            param=param,
            value=str(value),
            subpage="tutorial-start5GUplinkCCMTest.html")
